// Maps a failed execution to an ErrorCategory (lib/domain/automation.ts).
// Only the category, workflow name, node name and execution ID leave n8n:
// error messages, item data and stack traces may contain personal data, so
// they are used for classification here and then dropped.
const crypto = require('crypto');

const ev = $input.first().json;
const execution = ev.execution || {};
const err = execution.error || (ev.trigger && ev.trigger.error) || {};
const nodeName = (err.node && err.node.name) || execution.lastNodeExecuted || undefined;
const nodeType = (err.node && err.node.type) || '';
// httpCode is a status ("503") for HTTP errors, or a socket code ("ECONNREFUSED") for network errors.
const rawCode = err.httpCode || (err.context && err.context.httpCode) || (err.cause && err.cause.status) || '';
const httpCode = /^\d{3}$/.test(String(rawCode)) ? Number(rawCode) : NaN;
const text = [String(rawCode), err.message, err.description, err.name, err.code, err.cause && err.cause.code]
  .filter((v) => typeof v === 'string')
  .join(' ')
  .toLowerCase();

function categorize() {
  // Convex answers 503 {"error":"not_configured"} when CONVEX_INBOUND_SECRET is unset.
  if (/is not set|not[ _]configured/.test(text)) return 'not_configured';
  // Every HTTP node in these workflows calls Convex, which answers 401 only when it rejects our HMAC.
  if (httpCode === 401) return 'signature_rejected';
  if (httpCode >= 500) return 'upstream_5xx';
  if (httpCode >= 400) return 'upstream_4xx';
  if (/timeout|timed out|etimedout|esockettimedout|econnaborted/.test(text)) return 'timeout';
  // n8n rewrites socket errors ("The service refused the connection - perhaps it is offline").
  if (/econnrefused|enotfound|eai_again|econnreset|ehostunreach|socket hang up|network|refused the connection|dns|offline/.test(text)) return 'network';
  return 'delivery_failed';
}

const report = {
  executionId: String(execution.id || $execution.id),
  workflow: (ev.workflow && ev.workflow.name) || 'unknown',
  errorCategory: categorize(),
};
if (nodeName) report.node = nodeName;

console.log(
  `[lendloop] workflow error workflow="${report.workflow}" node="${report.node || '-'}" category=${report.errorCategory} execution=${report.executionId}${nodeType ? ` type=${nodeType}` : ''}`,
);

const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');
const rawBody = JSON.stringify(report);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`, 'utf8').digest('hex');

return [{ json: { ...report, rawBody, timestamp, signature } }];
